// Main Live Grid Render Function
const renderGrid = useCallback(
  async (
    tier: TierLevel,
    targetItem: SearchResultItem | null = selectedResult,
    parentProps: GridCellProperties | null = selectedCellProps
  ) => {
    if (!mapInstanceRef.current) return;
    const L = await import("leaflet");

    if (!gridLayerGroupRef.current) {
      gridLayerGroupRef.current = L.layerGroup().addTo(mapInstanceRef.current);
    } else {
      gridLayerGroupRef.current.clearLayers();
    }

    if (poiLayerGroupRef.current) {
      poiLayerGroupRef.current.clearLayers();
    }

    ensureSvgDefs(mapInstanceRef.current);
    setIsGridLoading(true);
    setServiceNotice(null);

    try {
      if (tier === 1) {
        // Fetch tiers diagnostic in background
        gridService.getGridTiers().catch(() => null);

        let features: GeoJsonFeature[] = [];
        try {
          const res = await gridService.getCells({ tier: 1, PageSize: 100 });
          if (res && res.success && res.data?.features && res.data.features.length > 0) {
            features = res.data.features;
          }
        } catch (apiErr: unknown) {
          const err = apiErr as { status?: number; isTransient?: boolean };
          if (err?.status === 502 || err?.isTransient) {
            setServiceNotice("Service waking up on Render (502). Falling back to cached grid.");
          }
        }

        currentTierFeaturesRef.current = features;

        if (features.length > 0) {
          features.forEach((feat) => {
            const props = feat.properties || {};
            const code = props.code || props.hierarchyCode || "";
            const isUnmasked = !(props.isMasked ?? !UAE_UNMASKED_CELLS.includes(code));
            const isSelected =
              code === (selectedCellIdRef.current || targetItem?.tiers.tier1);

            if (feat.geometry?.coordinates) {
              const ring = feat.geometry.coordinates[0];
              const latlngs: [number, number][] = ring.map(
                ([lon, lat]: [number, number]) => [lat, lon]
              );

              if (isUnmasked) {
                const fillColor = isSelected ? "#1B8CFE" : "#FFFFFF";
                const fillOpacity = isSelected ? 0.88 : 0.70;
                const strokeColor = isSelected ? "#0000FF" : "rgba(37, 99, 235, 0.45)";
                const strokeWidth = isSelected ? 2.2 : 1.2;

                const poly = L.polygon(latlngs, {
                  color: strokeColor,
                  weight: strokeWidth,
                  fillColor,
                  fillOpacity,
                  className: isSelected ? "selected-grid-cell" : "enabled-grid-cell",
                });

                poly.on("mouseover", () => {
                  if (selectedCellIdRef.current !== code) {
                    poly.setStyle({ fillOpacity: 0.85, color: "#1D4ED8", weight: 1.8 });
                  }
                });
                poly.on("mouseout", () => {
                  if (selectedCellIdRef.current !== code) {
                    poly.setStyle({ fillOpacity: 0.70, color: "rgba(37, 99, 235, 0.45)", weight: 1.2 });
                  }
                });

                poly.on("click", (e) => {
                  L.DomEvent.stopPropagation(e);
                  selectedCellIdRef.current = code;
                  setSelectedCellId(code);
                  setSelectedCellProps(props);
                  setActiveTier(2);
                  const cellBounds = poly.getBounds();
                  mapInstanceRef.current?.flyToBounds(cellBounds, {
                    duration: 1.0,
                    easeLinearity: 0.25,
                    padding: [24, 24],
                  });
                  setBreadcrumbs([
                    { tier: 1, label: "UAE (Tier 1)", code: "UAE" },
                    {
                      tier: 2,
                      label: `Cell ${code} (Tier 2)`,
                      code,
                      id: props.id || props.gridId,
                      cellProps: props,
                      bounds: [
                        [cellBounds.getSouth(), cellBounds.getWest()],
                        [cellBounds.getNorth(), cellBounds.getEast()],
                      ],
                    },
                  ]);
                  renderGridRef.current?.(2, targetItem, props);
                });

                poly.addTo(gridLayerGroupRef.current!);

                const textColor = isSelected ? "#FFFFFF" : "#0F172A";
                poly.bindTooltip(
                  `<div style="font-family: var(--font-cairo), Cairo, sans-serif; font-size: 13px; font-weight: 700; color: ${textColor}; text-align: center; line-height: 1.2; text-shadow: ${isSelected ? "none" : "0 0 3px rgba(255,255,255,0.9), 0 0 1px #FFFFFF"}; user-select: none;">${code}</div>`,
                  { permanent: true, direction: "center", className: "grid-cell-tooltip" }
                );
              } else if (gridTypeRef.current === "full-grid") {
                const poly = L.polygon(latlngs, {
                  color: "#DEDEDE",
                  weight: 0.8,
                  fillColor: "url(#uaeDisabledHatchPattern)",
                  fillOpacity: 1,
                  className: "disabled-grid-cell",
                  interactive: false,
                });
                poly.addTo(gridLayerGroupRef.current!);

                poly.bindTooltip(
                  `<div style="font-family: var(--font-cairo), Cairo, sans-serif; font-size: 13px; font-weight: 700; color: #94A3B8; text-align: center; line-height: 1.2; user-select: none;">${code}</div>`,
                  { permanent: true, direction: "center", className: "grid-cell-tooltip" }
                );
              }
            }
          });

          L.polygon(UAE_BORDER_COORDINATES, {
            color: "#2563EB",
            weight: 2.2,
            dashArray: "6 5",
            fillColor: "rgba(0, 0, 255, 0.05)",
            fillOpacity: 0.05,
            interactive: false,
          }).addTo(gridLayerGroupRef.current!);

          const uaeBounds: [[number, number], [number, number]] = [
            [TIER1_DEFAULT_BOUNDS.south, TIER1_DEFAULT_BOUNDS.west],
            [TIER1_DEFAULT_BOUNDS.north, TIER1_DEFAULT_BOUNDS.east],
          ];
          mapInstanceRef.current.flyToBounds(uaeBounds, { padding: [24, 24], duration: 1.0, easeLinearity: 0.25 });
        } else {
          renderFallbackTier1(L, targetItem);
        }

        if (targetItem) {
          updatePinMarker(targetItem.latitude, targetItem.longitude);
        }
      } else if (tier === 2) {
        const parentCode =
          parentProps?.code ||
          parentProps?.hierarchyCode ||
          selectedCellIdRef.current ||
          targetItem?.tiers.tier1 ||
          "46";
        const parentId = parentProps?.id || parentProps?.gridId;

        let childFeatures: GeoJsonFeature[] = [];
        try {
          if (parentId) {
            const res = await gridService.getCellChildren(parentId, { PageSize: 1000 });
            if (res?.success && res.data?.features?.length) {
              childFeatures = res.data.features;
            }
          }
          if (!childFeatures.length) {
            const res = await gridService.getCells({
              tier: 2,
              code: parentCode,
              PageSize: 1000,
            });
            if (res?.success && res.data?.features?.length) {
              childFeatures = res.data.features;
            }
          }
        } catch {
          // fallback
        }

        if (childFeatures.length > 0) {
          const allBounds = L.latLngBounds([]);
          childFeatures.forEach((feat) => {
            const props = feat.properties || {};
            const code = props.code || props.hierarchyCode || "";
            const isSelected =
              code === selectedCellIdRef.current || (!!targetItem?.tiers.tier2 && code.endsWith(targetItem.tiers.tier2));

            if (feat.geometry?.coordinates) {
              const ring = feat.geometry.coordinates[0];
              const latlngs: [number, number][] = ring.map(
                ([lon, lat]: [number, number]) => [lat, lon]
              );

              const poly = L.polygon(latlngs, {
                color: isSelected ? "#0000FF" : "rgba(37, 99, 235, 0.45)",
                weight: isSelected ? 2.2 : 1.2,
                fillColor: isSelected ? "#1B8CFE" : "#FFFFFF",
                fillOpacity: isSelected ? 0.88 : 0.70,
                className: isSelected ? "selected-grid-cell" : "enabled-grid-cell",
              });

              poly.on("mouseover", () => {
                if (selectedCellIdRef.current !== code) {
                  poly.setStyle({ fillOpacity: 0.85, color: "#1D4ED8", weight: 1.8 });
                }
              });
              poly.on("mouseout", () => {
                if (selectedCellIdRef.current !== code) {
                  poly.setStyle({ fillOpacity: 0.70, color: "rgba(37, 99, 235, 0.45)", weight: 1.2 });
                }
              });

              poly.on("click", (e) => {
                L.DomEvent.stopPropagation(e);
                selectedCellIdRef.current = code;
                setSelectedCellId(code);
                setSelectedCellProps(props);
                setActiveTier(3);
                const cellBounds = poly.getBounds();
                mapInstanceRef.current?.flyToBounds(cellBounds, {
                  duration: 1.0,
                  easeLinearity: 0.25,
                  padding: [24, 24],
                });
                setBreadcrumbs((prev) => [
                  ...prev.slice(0, 2),
                  {
                    tier: 3,
                    label: `Sector ${code} (Tier 3)`,
                    code,
                    id: props.id || props.gridId,
                    cellProps: props,
                    bounds: [
                      [cellBounds.getSouth(), cellBounds.getWest()],
                      [cellBounds.getNorth(), cellBounds.getEast()],
                    ],
                  },
                ]);
                renderGridRef.current?.(3, targetItem, props);
              });

              poly.addTo(gridLayerGroupRef.current!);
              allBounds.extend(poly.getBounds());

              const textColor = isSelected ? "#FFFFFF" : "#0F172A";
              const displayCode = code.includes(".") ? code.split(".").pop() : code;
              poly.bindTooltip(
                `<div style="font-family: var(--font-cairo), Cairo, sans-serif; font-size: 12px; font-weight: 700; color: ${textColor}; text-align: center; text-shadow: ${isSelected ? "none" : "0 0 3px rgba(255,255,255,0.9), 0 0 1px #FFFFFF"}">${displayCode}</div>`,
                { permanent: true, direction: "center", className: "grid-cell-tooltip" }
              );
            }
          });

          if (allBounds.isValid()) {
            mapInstanceRef.current.flyToBounds(allBounds, { duration: 1.0, easeLinearity: 0.25, padding: [30, 30] });
          }
        } else {
          renderFallbackTier2(L, parentCode, targetItem);
        }

        if (targetItem) {
          updatePinMarker(targetItem.latitude, targetItem.longitude);
        }
      } else if (tier === 3) {
        const parentCode =
          parentProps?.code ||
          parentProps?.hierarchyCode ||
          selectedCellIdRef.current ||
          "46.32";
        const parentId = parentProps?.id || parentProps?.gridId;

        let childFeatures: GeoJsonFeature[] = [];
        try {
          if (parentId) {
            const res = await gridService.getCellChildren(parentId, { PageSize: 1000 });
            if (res?.success && res.data?.features?.length) {
              childFeatures = res.data.features;
            }
          }
          if (!childFeatures.length) {
            const res = await gridService.getCells({
              tier: 3,
              code: parentCode,
              PageSize: 1000,
            });
            if (res?.success && res.data?.features?.length) {
              childFeatures = res.data.features;
            }
          }
        } catch {
          // fallback
        }

        if (childFeatures.length > 0) {
          const allBounds = L.latLngBounds([]);
          childFeatures.forEach((feat) => {
            const props = feat.properties || {};
            const code = props.code || props.hierarchyCode || "";
            const isSelected =
              code === selectedCellIdRef.current || (!!targetItem?.tiers.tier3 && code.endsWith(targetItem.tiers.tier3));

            if (feat.geometry?.coordinates) {
              const ring = feat.geometry.coordinates[0];
              const latlngs: [number, number][] = ring.map(
                ([lon, lat]: [number, number]) => [lat, lon]
              );

              const poly = L.polygon(latlngs, {
                color: isSelected ? "#0000FF" : "rgba(37, 99, 235, 0.45)",
                weight: isSelected ? 2.2 : 1.2,
                fillColor: isSelected ? "#1B8CFE" : "#FFFFFF",
                fillOpacity: isSelected ? 0.88 : 0.70,
                className: isSelected ? "selected-grid-cell" : "enabled-grid-cell",
              });

              poly.on("mouseover", () => {
                if (selectedCellIdRef.current !== code) {
                  poly.setStyle({ fillOpacity: 0.85, color: "#1D4ED8", weight: 1.8 });
                }
              });
              poly.on("mouseout", () => {
                if (selectedCellIdRef.current !== code) {
                  poly.setStyle({ fillOpacity: 0.70, color: "rgba(37, 99, 235, 0.45)", weight: 1.2 });
                }
              });

              poly.on("click", (e) => {
                L.DomEvent.stopPropagation(e);
                selectedCellIdRef.current = code;
