                color: isSelected ? "#0000FF" : "rgba(37, 99, 235, 0.45)",
                weight: isSelected ? 2.2 : 1.2,
                fillColor: isSelected ? "#1B8CFE" : "#FFFFFF",
                fillOpacity: isSelected ? 0.88 : 0.70,
                className: isSelected ? "selected-grid-cell" : "enabled-grid-cell",
              });

              poly.on("mouseover", () => {
                if (selectedCellIdRef.current !== code) {
                  poly.setStyle({ fillOpacity: 0.85, color: "#1D4ED8", weight: 1.8 });
                }
              });
              poly.on("mouseout", () => {
                if (selectedCellIdRef.current !== code) {
                  poly.setStyle({ fillOpacity: 0.70, color: "rgba(37, 99, 235, 0.45)", weight: 1.2 });
                }
              });

              poly.on("click", (e) => {
                L.DomEvent.stopPropagation(e);
                poly.setStyle({
                  fillColor: "#1B8CFE",
                  fillOpacity: 0.88,
                  color: "#0000FF",
                  weight: 2.2,
                });
                const textNode = (poly as unknown as { _svgTextNode?: SVGTextElement })._svgTextNode;
                if (textNode) {
                  textNode.setAttribute("fill", "#FFFFFF");
                  textNode.removeAttribute("stroke");
                }
                navigateToNextTier(
                  3,
                  poly.getBounds(),
                  code,
                  props,
                  targetItem,
                  `Sector ${code} (Tier 3)`
                );
              });

              poly.addTo(gridLayerGroupRef.current!);
              allBounds.extend(poly.getBounds());

              const textColor = isSelected ? "#FFFFFF" : "#0F172A";
              const displayCode = code.includes(".") ? code.split(".").pop() || code : code;
              bindSvgLabel(mapInstanceRef.current, poly, displayCode, { isSelected, textColor, fontSize: "12px" });
            }
          });

          if (allBounds.isValid() && !alreadyCentered) {
            mapInstanceRef.current.flyToBounds(allBounds, { duration: 1.0, easeLinearity: 0.25, padding: [30, 30] });
          }
        } else {
          renderFallbackTier2(L, parentCode, targetItem, alreadyCentered);
        }

        if (targetItem) {
          updatePinMarker(targetItem.latitude, targetItem.longitude);
        }
      } else if (tier === 3) {
        const parentCode =
          parentProps?.code ||
          parentProps?.hierarchyCode ||
          selectedCellIdRef.current ||
          "46.32";
        const parentId = parentProps?.id || parentProps?.gridId;

        let childFeatures: GeoJsonFeature[] = [];
        try {
          if (parentId) {
            const res = await gridService.getCellChildren(parentId, { PageSize: 1000 });
            if (res?.success && res.data?.features?.length) {
              childFeatures = res.data.features;
            }
          }
          if (!childFeatures.length) {
            const res = await gridService.getCells({
              tier: 3,
              code: parentCode,
              PageSize: 1000,
            });
            if (res?.success && res.data?.features?.length) {
              childFeatures = res.data.features;
            }
          }
        } catch {
          // fallback
        }

        if (childFeatures.length > 0) {
          const allBounds = L.latLngBounds([]);
          childFeatures.forEach((feat) => {
            const props = feat.properties || {};
            const code = props.code || props.hierarchyCode || "";
            const isSelected =
              code === selectedCellIdRef.current || (!!targetItem?.tiers.tier3 && code.endsWith(targetItem.tiers.tier3));

            if (feat.geometry?.coordinates) {
              const ring = feat.geometry.coordinates[0];
              const latlngs: [number, number][] = ring.map(
                ([lon, lat]: [number, number]) => [lat, lon]
              );

              const poly = L.polygon(latlngs, {
                color: isSelected ? "#0000FF" : "rgba(37, 99, 235, 0.45)",
                weight: isSelected ? 2.2 : 1.2,
                fillColor: isSelected ? "#1B8CFE" : "#FFFFFF",
                fillOpacity: isSelected ? 0.88 : 0.70,
                className: isSelected ? "selected-grid-cell" : "enabled-grid-cell",
              });

              poly.on("mouseover", () => {
                if (selectedCellIdRef.current !== code) {
                  poly.setStyle({ fillOpacity: 0.85, color: "#1D4ED8", weight: 1.8 });
                }
              });
              poly.on("mouseout", () => {
                if (selectedCellIdRef.current !== code) {
                  poly.setStyle({ fillOpacity: 0.70, color: "rgba(37, 99, 235, 0.45)", weight: 1.2 });
                }
              });

              poly.on("click", (e) => {
                L.DomEvent.stopPropagation(e);
                poly.setStyle({
                  fillColor: "#1B8CFE",
                  fillOpacity: 0.88,
                  color: "#0000FF",
                  weight: 2.2,
                });
                const textNode = (poly as unknown as { _svgTextNode?: SVGTextElement })._svgTextNode;
                if (textNode) {
                  textNode.setAttribute("fill", "#FFFFFF");
                  textNode.removeAttribute("stroke");
                }
                navigateToNextTier(
                  4,
                  poly.getBounds(),
                  code,
                  props,
                  targetItem,
                  `Block ${code} (Tier 4)`
                );
              });

              poly.addTo(gridLayerGroupRef.current!);
              allBounds.extend(poly.getBounds());

              const textColor = isSelected ? "#FFFFFF" : "#0F172A";
              const displayCode = code.includes(".") ? code.split(".").pop() || code : code;
              bindSvgLabel(mapInstanceRef.current, poly, displayCode, { isSelected, textColor, fontSize: "11px" });
            }
          });

          if (allBounds.isValid() && !alreadyCentered) {
            mapInstanceRef.current.flyToBounds(allBounds, { duration: 1.0, easeLinearity: 0.25, padding: [30, 30] });
          }
        } else {
          renderFallbackTier3(L, parentCode, targetItem, alreadyCentered);
        }

        if (targetItem) {
          updatePinMarker(targetItem.latitude, targetItem.longitude);
        }
      } else if (tier === 4) {
        const parentCode =
          parentProps?.code ||
          parentProps?.hierarchyCode ||
          selectedCellIdRef.current ||
          "46.32.82";
        const parentId = parentProps?.id || parentProps?.gridId;

        let childFeatures: GeoJsonFeature[] = [];
        try {
          if (parentId) {
            const res = await gridService.getCellChildren(parentId, { PageSize: 1000 });
            if (res?.success && res.data?.features?.length) {
              childFeatures = res.data.features;
            }
          }
          if (!childFeatures.length) {
            const res = await gridService.getCells({
              tier: 4,
              code: parentCode,
              PageSize: 1000,
            });
            if (res?.success && res.data?.features?.length) {
              childFeatures = res.data.features;
            }
          }
        } catch {
          // fallback
        }

        if (childFeatures.length > 0) {
          const allBounds = L.latLngBounds([]);
          const targetPlotCode = targetItem?.tiers.tier4 || "";

          childFeatures.forEach((feat) => {
            const props = feat.properties || {};
            const code = props.code || props.hierarchyCode || "";
            const isTargetPlot =
              code === selectedCellIdRef.current || (!!targetPlotCode && code.endsWith(targetPlotCode));
            const isNeighbor = selectedNeighborCodes.includes(props.id || code);

            if (feat.geometry?.coordinates) {
              const ring = feat.geometry.coordinates[0];
              const latlngs: [number, number][] = ring.map(
                ([lon, lat]: [number, number]) => [lat, lon]
              );

              const fillColor = isTargetPlot
                ? "#0000FF"
                : isNeighbor
                  ? "rgba(56, 189, 248, 0.25)"
                  : "#FFFFFF";
              const fillOpacity = isTargetPlot ? 0.85 : isNeighbor ? 0.35 : 0.45;
              const strokeColor = isTargetPlot ? "#0000FF" : isNeighbor ? "rgba(56, 189, 248, 0.8)" : "rgba(148, 163, 184, 0.6)";
              const strokeWidth = isTargetPlot ? 2.5 : 0.8;

              const poly = L.polygon(latlngs, {
                color: strokeColor,
                weight: strokeWidth,
                fillColor,
                fillOpacity,
                className: isTargetPlot ? "selected-plot-cell" : "plot-cell",
              });

              poly.on("click", async (e) => {
                L.DomEvent.stopPropagation(e);
                selectedCellIdRef.current = code;
                setSelectedCellId(code);
                setSelectedCellProps(props);

                poly.setStyle({
                  fillColor: "#0000FF",
                  fillOpacity: 0.85,
                  color: "#0000FF",
                  weight: 2.5,
                });
                const textNode = (poly as unknown as { _svgTextNode?: SVGTextElement })._svgTextNode;
                if (textNode) {
                  textNode.setAttribute("fill", "#FFFFFF");
                  textNode.removeAttribute("stroke");
                }

                // Fetch adjacent neighbors if ID available
                if (props.id) {
                  try {
                    const nRes = await gridService.getCellNeighbors(props.id);
                    if (nRes?.success && nRes.data?.length) {
                      setSelectedNeighborCodes(nRes.data.map((n) => n.cellId || n.hierarchyCode));
                    }
                  } catch {
                    // no-op
                  }
                }

                const bounds = poly.getBounds();
                const center = bounds.getCenter();
                mapInstanceRef.current?.flyTo(center, 18.5, { duration: 0.8 });
                updatePinMarker(center.lat, center.lng);
              });

              poly.addTo(gridLayerGroupRef.current!);
              allBounds.extend(poly.getBounds());

              const textColor = isTargetPlot ? "#FFFFFF" : "#1E293B";
              const displayCode = code.includes(".") ? code.split(".").pop() || code : code;
              bindSvgLabel(mapInstanceRef.current, poly, displayCode, { isSelected: isTargetPlot, textColor, fontSize: "11px" });
            }
          });

          renderPlotPOIs();
          if (allBounds.isValid() && !alreadyCentered) {
            mapInstanceRef.current.flyToBounds(allBounds, { duration: 1.0, easeLinearity: 0.25, padding: [25, 25] });
          }
        } else {
          renderFallbackTier4(L, parentCode, targetItem, alreadyCentered);
        }
      }
    } finally {
      setIsGridLoading(false);
    }
  },
  [
    selectedResult,
    selectedCellProps,
    selectedNeighborCodes,
    ensureSvgDefs,
    bindSvgLabel,
    navigateToNextTier,
    renderFallbackTier1,
    renderFallbackTier2,
    renderFallbackTier3,
    renderFallbackTier4,
    renderPlotPOIs,
    updatePinMarker,
  ]
);
